{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "The highest-transfer analogue SRT2104 (transfer 0.967) had absolute oral bioavailability of 13.8% in healthy volunteers, below the 20% threshold, directly supporting a low prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Revefenacin (transfer 0.906) showed <3% absolute oral bioavailability in humans, strongly below the threshold and supportive of low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "GHRP-6 (transfer 0.903), a peptide-like molecule, had systemic availability of only ~0.3% in humans after oral dosing, supporting low bioavailability for this peptidomimetic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Alvimopan (transfer 0.903) had human oral bioavailability of 6%, well below the 20% threshold, supporting a low prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Tilidine (transfer 0.884) had systemic bioavailability of 7.6% in humans, below the threshold and supportive of low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Aliskiren (transfer 0.850) had absolute oral bioavailability of 2.6% in healthy subjects, supporting a low prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Selegiline (transfer 0.845) had absolute oral bioavailability of 4% after a 10 mg oral dose in healthy volunteers, supporting low bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Octreotide (transfer 0.842), a peptide, had oral bioavailability of 0.6 ± 0.4% in healthy volunteers, supporting low bioavailability for the peptide-like query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to low absolute oral bioavailability: every relevant analogue with a direct human bioavailability measurement falls well below the 20% threshold, and the physicochemical prior also predicts poor absorption and solubility. No contradictory evidence was identified.",
  "evidence_gaps": [
    "No direct human oral bioavailability data exist for the exact query molecule.",
    "No permeability, efflux-transporter, or formulation-specific data are available for the query scaffold.",
    "The query is larger and more polar than most analogues, but this reinforces the low prediction rather than introducing uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

